using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using NextGenSoftware.OASIS.API.Core.Enums;
using NextGenSoftware.OASIS.API.Core.Holons;
using NextGenSoftware.OASIS.API.Core.Managers;
using NextGenSoftware.OASIS.API.Core.Queries;
using NextGenSoftware.OASIS.API.DNA;

namespace NextGenSoftware.OASIS.API.Providers.AlgorandOASIS.UnitTests;

[TestClass]
public sealed class AlgorandPublicAccountMetadataTests
{
    // Independent Python SHA512/256/Base32 vectors, not generated by the decoder under test.
    private static readonly string[] Keys = {
        "AAAQEAYEAUDAOCAJBIFQYDIOB4IBCEQTCQKRMFYYDENBWHA5DYP7MUPJQE",
        "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAY5HFKQ",
        "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAVIOOBQA"
    };

    private sealed class Native : HttpMessageHandler
    {
        public string Fault = "normal";
        public int Requests;

        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken token)
        {
            token.ThrowIfCancellationRequested();
            Requests++;
            Assert.AreEqual(HttpMethod.Get, request.Method);
            var path = request.RequestUri!.AbsolutePath;
            object result;
            if (path == "/versions")
                result = new { genesis_id = Fault == "network" ? "testnet-v1.0" : AlgorandPublicAccountMetadataSource.PublicNetwork,
                    genesis_hash_b64 = AlgorandPublicAccountMetadataSource.PublicGenesis };
            else if (path == "/v2/blocks/0")
                result = new Dictionary<string, object> {
                    ["genesis-id"] = AlgorandPublicAccountMetadataSource.PublicNetwork,
                    ["genesis-hash"] = Fault == "indexer-network" ? "wrong" : AlgorandPublicAccountMetadataSource.PublicGenesis,
                    ["round"] = 0 };
            else
            {
                Assert.AreEqual("?exclude=all", request.RequestUri.Query, "No rewind, scan or hidden fallback.");
                string key = path[13..];
                int index = Array.IndexOf(Keys, key);
                Assert.IsTrue(index >= 0);
                var row = new JsonObject {
                    ["address"] = Fault == "identity" ? Keys[(index + 1) % Keys.Length] : key,
                    ["round"] = 123 + index,
                    ["status"] = Fault == "status" ? "unknown" : "Offline",
                    ["amount"] = ulong.MaxValue,
                    ["amount-without-pending-rewards"] = ulong.MaxValue - 1,
                    ["pending-rewards"] = 1,
                    ["rewards"] = 0,
                    ["min-balance"] = 100000
                };
                if (Fault == "precision") row["amount"] = "18446744073709551615";
                if (Fault == "negative") row["amount"] = -1;
                if (Fault == "reward") row["pending-rewards"] = 2;
                if (Fault == "deleted") row["deleted"] = true;
                if (Fault == "last" && index == 2) row["address"] = "invalid";
                result = new JsonObject { ["current-round"] = Fault == "round" ? 0 : 123 + index, ["account"] = row };
            }
            string text = JsonSerializer.Serialize(result);
            if (Fault == "oversize") text = new string(' ', 262145);
            if (Fault == "duplicate") text = "{\"round\":0,\"round\":1}";
            return Task.FromResult(new HttpResponseMessage(Fault == "http" ? HttpStatusCode.BadGateway : HttpStatusCode.OK)
                { Content = new StringContent(text, Encoding.UTF8, "application/json") });
        }
    }

    [DataTestMethod]
    [DataRow("normal")] [DataRow("point")] [DataRow("window")] [DataRow("budget")]
    [DataRow("network")] [DataRow("indexer-network")] [DataRow("identity")]
    [DataRow("round")] [DataRow("status")] [DataRow("deleted")] [DataRow("reward")]
    [DataRow("precision")] [DataRow("negative")] [DataRow("last")]
    [DataRow("oversize")] [DataRow("duplicate")] [DataRow("http")]
    [DataRow("inactive")] [DataRow("cancel")] [DataRow("empty-window-error")]
    public async Task OnlyCompleteCurrentStateSelectionsEscape(string scenario)
    {
        var native = new Native();
        using var client = new HttpClient(native);
        using var source = new AlgorandPublicAccountMetadataSource(client, new Uri("https://algod.invalid/"),
            new Uri("https://indexer.invalid/"), Keys, Guid.NewGuid());
        if (scenario != "inactive")
        {
            var activated = await source.ActivateQuerySourceAsync(default);
            Assert.IsFalse(activated.IsError, activated.Exception?.ToString());
        }
        native.Requests = 0;
        native.Fault = scenario == "empty-window-error" ? "last" : scenario;

        var selected = Keys;
        var pointKey = Keys[0];
        var query = CosmicQuery<Holon>.Create(CosmicQueryScope.Named(ProviderType.AlgorandOASIS).Result)
            .Where(row => selected.Contains(CosmicQueryMetadata.Value<string>(row, AlgorandPublicAccountMetadataSource.AddressMetadata))).Result;
        if (scenario == "point")
            query = CosmicQuery<Holon>.Create(CosmicQueryScope.Named(ProviderType.AlgorandOASIS).Result)
                .Where(row => CosmicQueryMetadata.Value<string>(row, AlgorandPublicAccountMetadataSource.AddressMetadata) == pointKey).Result;
        if (scenario == "window") query = query.Skip(1).Result.Take(1).Result;
        if (scenario == "empty-window-error") query = query.Take(0).Result;
        var plan = CosmicQueryPlanner.Plan(query, ProviderType.AlgorandOASIS,
            new[] { new CosmicQueryTarget(ProviderType.AlgorandOASIS, source.QueryCapabilities) });
        Assert.IsFalse(plan.IsError, plan.Message);
        using var cancel = new CancellationTokenSource();
        if (scenario == "cancel") cancel.Cancel();
        var result = await source.ExecuteCosmicQueryAsync(plan.Result, scenario == "budget" ? 2 : 100, cancel.Token);
        if (scenario is "normal" or "point" or "window")
        {
            Assert.IsFalse(result.IsError, result.Exception?.ToString());
            Assert.AreEqual(scenario == "normal" ? 3 : 1, result.Result.Count);
            Assert.IsTrue(result.Result.All(row => row.IsPublic));
            Assert.AreEqual("18446744073709551615", result.Result[0].MetaData["AlgorandAmountMicroAlgos"]);
            Assert.AreEqual("Current", result.Result[0].MetaData["AlgorandConsistency"]);
        }
        else Assert.IsTrue(result.IsError, "No partial page may escape.");
        if (scenario is "inactive" or "cancel") Assert.AreEqual(0, native.Requests);
    }

    [TestMethod]
    public void CanonicalAddressAndExplicitCurrentConfigRequired()
    {
        foreach (string key in Keys) Assert.AreEqual(key, AlgorandPublicAccountMetadataSource.ValidateAddress(key));
        foreach (string key in new[] { Keys[0].ToLowerInvariant(), Keys[0] + "=", new string('A', 58) })
            Assert.ThrowsException<ArgumentException>(() => AlgorandPublicAccountMetadataSource.ValidateAddress(key));
        Assert.ThrowsException<ArgumentException>(() => AlgorandPublicAccountMetadataSource.FromJson("{\"round\":123}"));
    }

    [TestMethod]
    [TestCategory("NativeAlgorandPublic")]
    public async Task RetainedNativeCatalogueRunsSharedManagerThreeAndTwo()
    {
        string? path = Environment.GetEnvironmentVariable("COSMIC_ALGORAND_PUBLIC_SOURCE");
        if (string.IsNullOrEmpty(path)) Assert.Inconclusive("Explicit retained catalogue required.");
        string json = await File.ReadAllTextAsync(path!);
        using var source = AlgorandPublicAccountMetadataSource.FromJson(json);
        using var configuration = JsonDocument.Parse(json);
        var keys = configuration.RootElement.GetProperty("accounts").EnumerateArray().Select(row => row.GetString()!).ToArray();
        Assert.IsFalse((await source.ActivateQuerySourceAsync(default)).IsError);
        var dna = new OASISDNA { OASIS = new NextGenSoftware.OASIS.API.DNA.OASIS { HyperDriveMode = HyperDriveModes.V2 } };
        var manager = new HolonManager(null, dna, new ProviderManager(null, dna));
        using var output = new StringWriter();
        var actor = Guid.NewGuid();
        var full = await CosmicCqlDemo.NativeKeySetWalkthrough.RunAsync(manager, source, keys, actor, output);
        var subset = await CosmicCqlDemo.NativeKeySetWalkthrough.RunAsync(manager, source, keys.Take(2), actor, output);
        Assert.AreEqual(3, full.Count);
        Assert.AreEqual(2, subset.Count);
    }
}
